import { NextFunction, Request, Response, Router } from "express";
import { AdvanceOrderUseCase } from "../application/AdvanceOrderUseCase";
import { CancelOrderUseCase } from "../application/CancelOrderUseCase";
import { GetOrderUseCase } from "../application/GetOrderUseCase";
import { ListOrdersByStateUseCase } from "../application/ListOrdersByStateUseCase";
import { OrderLineDto } from "../application/OrderDto";
import { PlaceOrderUseCase } from "../application/PlaceOrderUseCase";

type Handler = (req: Request, res: Response) => void;

const ADVANCE_ACTIONS = {
  pay: "paid",
  pack: "packed",
  ship: "shipped",
  deliver: "delivered",
} as const;

export class OrderController {
  constructor(
    private readonly placeOrder: PlaceOrderUseCase,
    private readonly getOrder: GetOrderUseCase,
    private readonly listOrders: ListOrdersByStateUseCase,
    private readonly advanceOrder: AdvanceOrderUseCase,
    private readonly cancelOrder: CancelOrderUseCase,
  ) {}

  router(): Router {
    const router = Router();
    router.post("/", this.guard(this.place));
    router.get("/", this.guard(this.list));
    router.get("/:id", this.guard(this.get));
    router.post("/:id/cancel", this.guard(this.cancel));
    router.post("/:id/:action", this.guard(this.advance));
    return router;
  }

  private guard(handler: Handler) {
    return (req: Request, res: Response, next: NextFunction): void => {
      try {
        handler.call(this, req, res);
      } catch (error) {
        next(error);
      }
    };
  }

  private place(req: Request, res: Response): void {
    res.status(201).json(this.placeOrder.execute(parseLines(req.body)));
  }

  private list(req: Request, res: Response): void {
    const state = typeof req.query.state === "string" ? req.query.state : undefined;
    res.json(this.listOrders.execute(state));
  }

  private get(req: Request, res: Response): void {
    res.json(this.getOrder.execute(String(req.params.id)));
  }

  private cancel(req: Request, res: Response): void {
    res.json(this.cancelOrder.execute(String(req.params.id)));
  }

  private advance(req: Request, res: Response): void {
    const action = String(req.params.action);
    if (!Object.prototype.hasOwnProperty.call(ADVANCE_ACTIONS, action)) {
      res.status(404).json({ error: `Unknown action: ${action}` });
      return;
    }
    const target = ADVANCE_ACTIONS[action as keyof typeof ADVANCE_ACTIONS];
    res.json(this.advanceOrder.execute(String(req.params.id), target));
  }
}

function parseLines(body: unknown): OrderLineDto[] {
  const lines = (body as { lines?: unknown } | undefined)?.lines;
  if (!Array.isArray(lines)) {
    throw new BadRequestError("Body must contain a 'lines' array");
  }
  return lines.map((raw: unknown) => {
    const line = raw as { productId?: unknown; quantity?: unknown } | null;
    if (typeof line?.productId !== "string" || typeof line.quantity !== "number") {
      throw new BadRequestError("Each line needs a string 'productId' and a numeric 'quantity'");
    }
    return { productId: line.productId, quantity: line.quantity };
  });
}

export class BadRequestError extends Error {}

